import React from 'react';

/** Agent state values. */
export type AgentStatusValue = 'idle' | 'thinking' | 'acting' | 'done' | 'error';

/** Props for the {@link AgentStatus} component. */
export interface AgentStatusProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current agent status. */
  status: AgentStatusValue;
  /** Override label text. Defaults to the status name. */
  label?: string;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * Agent state indicator with dot and label.
 * Renders a `<div>` with `sk-agent-status` and `data-status`.
 */
export const AgentStatus = React.forwardRef<HTMLDivElement, AgentStatusProps>(
  ({ status, label, className, ...rest }, ref) => {
    const defaultLabels: Record<AgentStatusValue, string> = {
      idle: 'idle',
      thinking: 'thinking',
      acting: 'acting',
      done: 'done',
      error: 'error',
    };
    return (
      <div
        ref={ref}
        className={`sk-agent-status${className ? ` ${className}` : ''}`}
        data-status={status}
        role="status"
        aria-live="polite"
        {...rest}
      >
        <span className="sk-agent-status__dot" />
        <span className="sk-agent-status__label">{label ?? defaultLabels[status]}</span>
      </div>
    );
  },
);

AgentStatus.displayName = 'AgentStatus';

/**
 * skeehn — AgentStatus Component
 *
 * @component sk-agent-status
 * @statuses  idle | thinking | acting | done | error
 * @variants  default | compact | full
 * @slots     __indicator __text __step-progress __step-label
 * @a11y      Status text always present alongside color, aria-live
 * @design    Visible dot w/ glow, readable step bars + labels.
 */

.sk-agent-status { display: inline-flex; align-items: center; gap: var(--sk-space-2); padding: var(--sk-space-2) var(--sk-space-3); border: var(--sk-border); border-radius: var(--sk-radius-sm); font-family: var(--sk-font-mono); font-size: var(--sk-font-size-sm); background: hsl(var(--sk-surface)); }
.sk-agent-status__indicator { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; background: hsl(var(--sk-muted-foreground)); }
.sk-agent-status__text { color: hsl(var(--sk-muted-foreground)); letter-spacing: var(--sk-letter-spacing-wide); }
.sk-agent-status[data-status="thinking"] .sk-agent-status__indicator { background: hsl(var(--sk-info)); }
.sk-agent-status[data-status="thinking"][data-pulse="true"] .sk-agent-status__indicator { box-shadow: 0 0 8px hsl(var(--sk-info) / 0.6); animation: sk-dither-pulse 1.5s ease-in-out infinite; }
.sk-agent-status[data-status="acting"] .sk-agent-status__indicator { background: hsl(var(--sk-warning)); box-shadow: 0 0 8px hsl(var(--sk-warning) / 0.6); animation: sk-dither-pulse 0.8s ease-in-out infinite; }
.sk-agent-status[data-status="done"] .sk-agent-status__indicator { background: hsl(var(--sk-success)); }
.sk-agent-status[data-status="error"] .sk-agent-status__indicator { background: hsl(var(--sk-destructive)); }
.sk-agent-status[data-status="error"] .sk-agent-status__text { color: hsl(var(--sk-destructive)); }
.sk-agent-status[data-variant="compact"] { padding: var(--sk-space-1) var(--sk-space-2); font-size: var(--sk-font-size-xs); }
.sk-agent-status[data-variant="compact"] .sk-agent-status__indicator { width: 8px; height: 8px; }
.sk-agent-status[data-variant="full"] { display: flex; width: 100%; justify-content: center; border: none; background: transparent; }

/* Multi-step progress — readable bars + labels */
.sk-agent-status__steps { display: flex; align-items: center; gap: var(--sk-space-1); margin-top: var(--sk-space-2); }
.sk-agent-status__step { width: 1.75rem; height: 4px; border-radius: 999px; background: hsl(var(--sk-border-color)); position: relative; }
.sk-agent-status__step[data-state="completed"] { background: hsl(var(--sk-success)); }
.sk-agent-status__step[data-state="active"] { background: hsl(var(--sk-info)); animation: sk-pulse-dither 1s ease-in-out infinite; }
.sk-agent-status__step[data-state="error"] { background: hsl(var(--sk-destructive)); }
.sk-agent-status__step-label { font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs); color: hsl(var(--sk-muted-foreground) / 0.75); letter-spacing: var(--sk-letter-spacing-wide); margin-top: var(--sk-space-1); text-align: center; }

/* Loading & skeleton */
.sk-agent-status[data-loading] { pointer-events: none; opacity: 0.6; }
.sk-agent-status[data-loading] .sk-agent-status__indicator { animation: sk-pulse-dither 1s ease-in-out infinite; }
.sk-agent-status[data-skeleton] { pointer-events: none; }
.sk-agent-status[data-skeleton] .sk-agent-status__text { color: transparent; background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-secondary)) 50%, hsl(var(--sk-muted)) 75%); background-size: 200% 100%; animation: sk-shimmer 1.8s ease-in-out infinite; border-radius: var(--sk-radius-sm); }

@media print {
  .sk-agent-status { border: none; }
  .sk-agent-status__indicator { display: none; }
  .sk-agent-status[data-skeleton] { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .sk-agent-status[data-status="thinking"][data-pulse="true"] .sk-agent-status__indicator,
  .sk-agent-status[data-status="acting"] .sk-agent-status__indicator,
  .sk-agent-status__step[data-state="active"],
  .sk-agent-status[data-loading] .sk-agent-status__indicator { animation: none; }
  .sk-agent-status[data-skeleton] .sk-agent-status__text { animation: none; background: hsl(var(--sk-muted)); }
}
